{
  "a_sentences": [
    {
      "a_text": "P1 expose que l'assureur (la recourante) a déposé devant le tribunal arbitral la même demande que l'assuré avait formulée devant le tribunal administratif cantonal, tendant à la prise en charge par l'assureur des prestations de soins prodiguées en 2021 et 2022.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "P2 indique que ce dépôt simultané de deux procédures portant sur la même prétention donne l'apparence que l'assureur cherche à faire valoir une seconde fois le droit de l'assuré.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "P3 précise que l'art. 89 al. 1 LAMal institue un tribunal arbitral pour trancher les litiges entre assureurs et fournisseurs de prestations.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "P4 rappelle que la compétence du tribunal arbitral s'étend à toutes les contestations entre assureurs et fournisseurs qui concernent des relations juridiques découlant ou fondées sur la LAMal.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "P5 indique que le choix entre le système du tiers payant et du tiers garant n'influence pas la compétence du tribunal arbitral.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "P6 conclut que le Tribunal fédéral confirme le refus d'entrer en matière de la juridiction cantonale, dès lors que la demande porte en réalité sur le droit de l'assuré à la prise en charge par l'assureur, et non sur un litige entre assureur et fournisseur.",
      "b_propositions": ["P6"]
    }
  ]
}
